import{_ as t,o as d,c as r,Q as a}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"软件工程师求职邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/11-software-engineer-job-application.md","filePath":"zh/more/maltese/practice/emails/11-software-engineer-job-application.md"}'),e={name:"zh/more/maltese/practice/emails/11-software-engineer-job-application.md"},o=a('<h1 id="软件工程师求职邮件" tabindex="-1">软件工程师求职邮件 <a class="header-anchor" href="#软件工程师求职邮件" aria-label="Permalink to &quot;软件工程师求职邮件&quot;">​</a></h1><p><strong>场景：</strong> 申请人写信给科技公司，申请软件工程师职位。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:info@tech.com" target="_blank" rel="noreferrer">info@tech.com</a><strong>Mingħand（发件人 From）：</strong> [isem]@email.com <strong>Data（日期）：</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Applikazzjoni ta&#39; xogħol ta&#39; inġinier tas-softwer</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@tech.com" target="_blank" rel="noreferrer">info@tech.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; inġinier tas-softwer</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-pożizzjoni ta&#39; inġinier tas-softwer.</p><p>Għandi lawrja fil-kompjuter u esperjenza ta&#39; ħames snin fl-iżvilupp tas-softwer.</p><p>Naf il-lingwi tal-programmar bħal Java, Python u JavaScript.</p><p>Naħdem fuq proġetti bħal apps u websajts.</p><p>Jien kreattiv u nsolvi l-problemi b&#39;mod effiċjenti.</p><p>Naħdem tajjeb f&#39;tim u wkoll waħdi.</p><p>Jimpurtani mill-kwalità u mid-dettalji.</p><p>Nixtieq inkun parti mit-tim tagħkom.</p><p>Nispera li niltaqgħu għal intervista dalwaqt.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@tech.com" target="_blank" rel="noreferrer">info@tech.com</a></p><p><strong>整句：</strong> 收件人（To）：info@tech.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:info@tech.com" target="_blank" rel="noreferrer">info@tech.com</a></td><td>邮箱地址</td><td>科技公司的招聘邮箱（示例）</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>整句：</strong> 发件人（From）：[你的名字]@email.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td>[isem]@email.com</td><td>邮箱地址</td><td>你的邮箱占位，请替换为真实邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 15 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>15</td><td>十五</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; inġinier tas-softwer</p><p><strong>整句：</strong> 主题：软件工程师职位申请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Applikazzjoni</td><td>申请</td><td>阴性名词，借词 application</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>xogħol</td><td>工作；职位</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>inġinier</td><td>工程师</td><td>阳性名词，借词 engineer</td></tr><tr><td>tas-softwer</td><td>软件的</td><td><code>ta&#39;</code> + <code>is-softwer</code> 缩合</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>整句：</strong> 亲爱的先生 / 女士：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形式</td></tr><tr><td>Sinjur</td><td>先生</td><td>阳性名词</td></tr><tr><td>/</td><td>或</td><td>表示二选一</td></tr><tr><td>Sinjura</td><td>女士</td><td>阴性名词</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-pożizzjoni ta&#39; inġinier tas-softwer.</p><p><strong>整句：</strong> 我写信是为了申请软件工程师职位。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在（进行时标记）</td><td>与动词连用表示正在做某事</td></tr><tr><td>nikteb</td><td>我写</td><td>第一人称单数现在时</td></tr><tr><td>biex</td><td>为了</td><td>引出目的状语</td></tr><tr><td>napplika</td><td>我申请</td><td>第一人称单数形式，借词 apply</td></tr><tr><td>għall-pożizzjoni</td><td>申请职位</td><td><code>għal</code> + <code>il-pożizzjoni</code> 缩合</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>inġinier</td><td>工程师</td><td>阳性名词，借词 engineer</td></tr><tr><td>tas-softwer</td><td>软件的</td><td><code>ta&#39;</code> + <code>is-softwer</code> 缩合</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi lawrja fil-kompjuter u esperjenza ta&#39; ħames snin fl-iżvilupp tas-softwer.</p><p><strong>整句：</strong> 我有计算机学位和五年的软件开发经验。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>lawrja</td><td>学位</td><td>阴性名词，借词 laurea</td></tr><tr><td>fil-kompjuter</td><td>在计算机方面</td><td><code>f&#39;</code> + <code>il-kompjuter</code> 缩合</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>esperjenza</td><td>经验</td><td>阴性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>ħames</td><td>五</td><td>数词</td></tr><tr><td>snin</td><td>年</td><td><code>sena</code> 的复数形式</td></tr><tr><td>fl-iżvilupp</td><td>在发展方面</td><td><code>f&#39;</code> + <code>l-iżvilupp</code> 缩合</td></tr><tr><td>tas-softwer</td><td>软件的</td><td><code>ta&#39;</code> + <code>is-softwer</code> 缩合</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Naf il-lingwi tal-programmar bħal Java, Python u JavaScript.</p><p><strong>整句：</strong> 我熟悉 Java、Python 和 JavaScript 等编程语言。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naf</td><td>我知道；我熟悉</td><td>第一人称单数形式</td></tr><tr><td>il-lingwi</td><td>语言</td><td><code>lingwa</code> 的复数，带定冠词</td></tr><tr><td>tal-programmar</td><td>编程的</td><td><code>ta&#39;</code> + <code>il-programmar</code> 缩合</td></tr><tr><td>bħal</td><td>比如；如同</td><td>介词</td></tr><tr><td>Java</td><td>Java</td><td>编程语言名</td></tr><tr><td>Python</td><td>Python</td><td>编程语言名</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>JavaScript</td><td>JavaScript</td><td>编程语言名</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Naħdem fuq proġetti bħal apps u websajts.</p><p><strong>整句：</strong> 我参与开发应用程序和网站等项目。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naħdem</td><td>我工作</td><td>第一人称单数现在时</td></tr><tr><td>fuq</td><td>在……上；从事</td><td>介词</td></tr><tr><td>proġetti</td><td>项目</td><td><code>proġett</code> 的复数形式</td></tr><tr><td>bħal</td><td>比如</td><td>介词</td></tr><tr><td>apps</td><td>应用程序</td><td>借词 app 的复数</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>websajts</td><td>网站</td><td>借词 website 的复数</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Jien kreattiv u nsolvi l-problemi b&#39;mod effiċjenti.</p><p><strong>整句：</strong> 我富有创造力，并且能高效地解决问题。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>第一人称单数代词</td></tr><tr><td>kreattiv</td><td>有创造力的</td><td>形容词，借词 creative</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>nsolvi</td><td>我解决</td><td>第一人称单数现在时</td></tr><tr><td>l-problemi</td><td>问题</td><td><code>problema</code> 的复数，带定冠词</td></tr><tr><td>b&#39;mod</td><td>以……方式</td><td><code>b&#39;</code> + <code>mod</code>“方式”</td></tr><tr><td>effiċjenti</td><td>高效的</td><td>形容词，借词 efficient</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Naħdem tajjeb f&#39;tim u wkoll waħdi.</p><p><strong>整句：</strong> 我在团队中表现良好，也能独立工作。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naħdem</td><td>我工作</td><td>第一人称单数现在时</td></tr><tr><td>tajjeb</td><td>好</td><td>此处作副词“很好地”</td></tr><tr><td>f&#39;tim</td><td>在团队中</td><td><code>f&#39;</code>“在” + <code>tim</code>“团队”</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>wkoll</td><td>也</td><td>副词</td></tr><tr><td>waħdi</td><td>独自地</td><td>反身表达“我一个人”</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Jimpurtani mill-kwalità u mid-dettalji.</p><p><strong>整句：</strong> 我在意质量，也注重细节。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jimpurtani</td><td>我在意</td><td><code>jimpurta</code> + <code>-ni</code>“我”，惯用表达</td></tr><tr><td>mill-kwalità</td><td>关于质量</td><td><code>minn</code> + <code>il-kwalità</code> 缩合</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>mid-dettalji</td><td>关于细节</td><td><code>minn</code> + <code>id-dettalji</code>（复数）缩合</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq inkun parti mit-tim tagħkom.</p><p><strong>整句：</strong> 我希望成为你们团队的一员。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nixtieq</td><td>我想要；我希望</td><td>礼貌表达愿望</td></tr><tr><td>inkun</td><td>我会是；成为</td><td>第一人称单数形式</td></tr><tr><td>parti</td><td>部分；一员</td><td>阴性名词</td></tr><tr><td>mit-tim</td><td>团队的</td><td><code>minn</code> + <code>it-tim</code> 缩合</td></tr><tr><td>tagħkom</td><td>你们的</td><td>复数所有格代词</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li niltaqgħu għal intervista dalwaqt.</p><p><strong>整句：</strong> 我希望很快能进行面试。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>niltaqgħu</td><td>我们见面</td><td>第一人称复数形式</td></tr><tr><td>għal</td><td>为了</td><td>介词</td></tr><tr><td>intervista</td><td>面试</td><td>阴性名词，借词 interview</td></tr><tr><td>dalwaqt</td><td>很快</td><td>副词</td></tr></tbody></table><h3 id="_10" tabindex="-1">10. <a class="header-anchor" href="#_10" aria-label="Permalink to &quot;10.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>整句：</strong> 感谢你们考虑我的申请。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>talli</td><td>因为（你们）……</td><td>引出原因的书面表达</td></tr><tr><td>qiesu</td><td>他们考虑了</td><td><code>qies</code> 的第三人称复数过去时</td></tr><tr><td>l-applikazzjoni</td><td>申请</td><td>阴性名词，带定冠词</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>整句：</strong> 此致敬意，[你的名字]（正式邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Ismek</td><td>你的名字</td><td><code>isem</code>“名字” + <code>-ek</code>“你的”；请替换为真实姓名</td></tr></tbody></table>',65),i=[o];function n(l,h,s,p,c,b){return d(),r("div",null,i)}const u=t(e,[["render",n]]);export{m as __pageData,u as default};
